def pedido_del_obrero_al_mostrador(propuesta, material, raiz):
    """Lleva al mostrador el pedido que el obrero hace en su propia propuesta.

    La llama la comprobacion de la propuesta del obrero en el renglon 1537 de
    cuerpo/obrero.py, cuando la propuesta trae la marca de que no encontro algo
    y su pregunta obligatoria. En esta ronda solo se deja escrita y lista; el
    enganche en ese tramo va en la ronda siguiente.

    propuesta : el diccionario que devolvio el obrero. Puede traer dentro su
                PREGUNTA_REQUERIDA con los archivos y nombres de pieza que pide.
    material  : texto. El material que ya tenia.
    raiz      : texto. La carpeta del proyecto.
    devuelve  : el material con las piezas pedidas pegadas al final. Si el
                obrero no pidio nada, o no se pudo traer ninguna, devuelve el
                material TAL CUAL, sin tocarlo.
    """
    try:
        from arnes.mostrador import lo_que_pide, atender
    except Exception:
        return material

    if not isinstance(propuesta, dict):
        return material

    texto_respuesta = propuesta.get("PREGUNTA_REQUERIDA")
    if not texto_respuesta:
        return material

    try:
        peticiones = lo_que_pide(texto_respuesta)
    except Exception:
        return material

    if not peticiones:
        return material

    try:
        traido = atender(peticiones, raiz)
    except Exception:
        return material

    if not traido:
        return material

    if not isinstance(traido, str):
        traido = str(traido)

    if not traido:
        return material

    if traido in material:
        return material

    return material + traido


